function mv_wb_icon(string $n, int $size = 40): string
{
    return '<svg viewBox="0 0 64 64" width="' . $size . '" height="' . $size . '" aria-hidden="true">' . (MV_WB_ICONS[$n] ?? MV_WB_ICONS['stern']) . '</svg>';
}

function mv_wb_pose(string $name): string
{
    $n = mb_strtolower($name);
    foreach (['p-band' => ['band'], 'p-hocke' => ['malasana', 'hocke'], 'p-haende' => ['massage', 'gegendruck', 'kiefer'], 'p-seit' => ['seitlage', 'clamshell', 'open book', 'seitstütz', 'aufstehen über'], 'p-vier' => ['katze', 'bird dog', 'vierfüßler', 'wiegen', 'kindhaltung'], 'p-lieg' => ['rücken', 'brücke', 'bridge', 'heel', 'toe', 'dead bug', 'beine an die wand', 'atmung', 'aktivierung', 'diastase', 'transversus', 'atem'], 'p-sitz' => ['sitzen', 'beckenboden finden', 'schütteln']] as $ic => $keys)
        foreach ($keys as $k) if (str_contains($n, $k)) return $ic;
    return 'p-stand';
}
